  function renderEntry(){const user=currentUser(),sectorId=user.sectorId,d=today(),events=accessibleEvents().filter(e=>e.date===d),pendingEvents=events.filter(e=>!e.submissionId),dailySubmissions=(state.submissions||[]).filter(s=>s.date===d&&s.sectorId===sectorId),locked=reportLocked(d,sectorId);return`
    <div class="page-intro"><div><h2>Saisie du ${fmtDate(d)}</h2><p><b>${esc(sector(sectorId).name)} — Surveillant général : ${esc(sector(sectorId).supervisor)}</b> · Plusieurs soumissions autorisées · Fermeture automatique à 18 h 00</p></div><span class="tag ${locked?"red":dailySubmissions.length?"blue":"amber"}">${locked?"Verrouillé":`${dailySubmissions.length} rapport(s) soumis`}</span></div>
    <div class="kpi-grid"><div class="kpi"><div class="kpi-label">ÉVÉNEMENTS SAISIS</div><div class="kpi-value">${events.length}</div><div class="kpi-sub">${pendingEvents.length} à inclure dans le prochain rapport</div></div><div class="kpi"><div class="kpi-label">HEURES D’ABSENCE COMPTÉES</div><div class="kpi-value">${events.filter(e=>e.type==="absence"&&e.status!=="justified").length} h</div><div class="kpi-sub">Les absences justifiées sont exclues</div></div><div class="kpi"><div class="kpi-label">RAPPORTS SOUMIS</div><div class="kpi-value">${dailySubmissions.length}</div><div class="kpi-sub">Lots verrouillés pour le surveillant</div></div><div class="kpi"><div class="kpi-label">VERROUILLAGE FINAL</div><div class="kpi-value">18 h</div><div class="kpi-sub">Heure du Cameroun</div></div></div>
    <section class="card"><div class="card-head"><h3>Événements de mon secteur</h3>${!locked?'<button class="btn primary" data-action="open-event">+ Saisir une anomalie</button>':''}</div><div class="table-wrap"><table><thead><tr><th>N°</th><th>Horaire</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Classe</th><th>Matière</th><th>Type</th><th>Statut</th><th>Secteur</th><th></th></tr></thead><tbody>${eventRows(events)}</tbody></table></div></section>
    <section class="card" style="margin-top:18px"><div class="card-body"><h3>Soumettre un rapport journalier</h3><p class="muted">Cette soumission contiendra ${pendingEvents.length?`${pendingEvents.length} nouvel(aux) événement(s)`:"la mention « Néant »"}. Après la soumission, ces événements ne pourront plus être modifiés par le surveillant général.</p><label class="attestation"><input id="reportAttestation" type="checkbox" ${locked?"disabled":""}> Je confirme l’exactitude des événements contenus dans ce rapport. Les cours non signalés se sont déroulés normalement.</label><button class="btn dark" style="margin-top:14px" data-action="submit-daily" ${locked?"disabled":""}>Soumettre le rapport n° ${dailySubmissions.length+1}</button></div></section>`}

  function renderDashboard(){const d=today(),events=accessibleEvents().filter(e=>e.date===d),abs=events.filter(e=>e.type==="absence"&&e.status!=="justified"),ret=events.filter(e=>e.type==="retard"),classes=new Set(abs.flatMap(e=>[e.className,...(e.jointClasses||[])])),conf=state.confirmations[d]||{},sectorList=isSupervisor()?[sector(currentUser().sectorId)]:state.sectors,submitted=sectorList.filter(s=>["submitted","approved"].includes(conf[s.id]?.status)).length,ranking=aggregate(abs).slice(0,3);return`
    <div class="page-intro"><div><h2>État des absences — Aujourd’hui</h2><p>${fmtDate(d)} · Mise à jour ${new Date().toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}</p></div><div class="filter-row"><button class="btn dark" data-page="reports">Rapport intermédiaire</button></div></div>
    <div class="kpi-grid"><div class="kpi"><div class="kpi-label">HEURES D’ABSENCE</div><div class="kpi-value">${abs.length} h</div><div class="kpi-sub">Justifiées exclues</div></div><div class="kpi"><div class="kpi-label">RETARDS</div><div class="kpi-value">${ret.length}</div><div class="kpi-sub">Suivis séparément</div></div><div class="kpi"><div class="kpi-label">CLASSES TOUCHÉES</div><div class="kpi-value">${classes.size}</div><div class="kpi-sub">Heures de cours perdues</div></div><div class="kpi"><div class="kpi-label">RAPPORTS SOUMIS</div><div class="kpi-value">${submitted}/${sectorList.length}</div><div class="kpi-sub">${sectorList.length-submitted} encore en attente</div></div></div>
    <div class="layout-two"><section class="card"><div class="card-head"><h3>Événements reçus</h3><button class="btn ghost" data-page="events">Voir tout</button></div><div class="table-wrap"><table><thead><tr><th>N°</th><th>Horaire</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Classe</th><th>Matière</th><th>Type</th><th>Statut</th><th>Secteur</th><th></th></tr></thead><tbody>${eventRows(events.slice(0,7))}</tbody></table></div></section>
    <div class="stack"><section class="card"><div class="card-head"><h3>Transmission des secteurs</h3><span class="tag blue">Aujourd’hui</span></div><div class="card-body">${sectorList.map(s=>{const r=conf[s.id],st=r?.status||"draft";return`<div class="sector-row"><div><b><span class="dot ${st==="approved"?"green":st==="submitted"?"amber":"gray"}"></span>${esc(s.name)}</b><small><b>Surveillant général : ${esc(s.supervisor)}</b><br>${st==="approved"?"Approuvé par l’administration":st==="submitted"?"Validé et soumis par le surveillant":st==="rejected"?"Rejeté pour correction":"Non soumis"}</small></div>${isAdmin()&&st==="submitted"?`<button class="tag green" data-action="confirm-sector" data-id="${s.id}">Approuver</button>`:`<span class="tag ${st==="approved"?"green":st==="submitted"?"blue":"gray"}">${st==="approved"?"Approuvé":st==="submitted"?"Soumis":"En attente"}</span>`}</div>`}).join("")}</div></section>
    <section class="card"><div class="card-head"><h3>Top enseignants · Semaine</h3></div><div class="card-body">${ranking.length?ranking.map((r,i)=>`<div class="rank-row"><span class="rank-no">${i+1}</span><div><b>${esc(r.teacher.name)}</b><small>${esc(r.teacher.specialty)}</small></div><span class="hours">${r.hours} h</span></div>`).join(""):"<div class='empty'>Aucune donnée</div>"}</div></section></div></div>`}

  function renderSchedule(){
    const dayNames={1:"Lundi",2:"Mardi",3:"Mercredi",4:"Jeudi",5:"Vendredi"},allowedSectors=isSupervisor()?[sector(currentUser().sectorId)]:state.sectors;
    const sectorFilter=isSupervisor()?currentUser().sectorId:(allowedSectors.some(s=>s.id===state.scheduleSectorFilter)?state.scheduleSectorFilter:"");
    const availableClasses=[...new Set(allowedSectors.filter(s=>!sectorFilter||s.id===sectorFilter).flatMap(s=>s.classes||[]))].sort((a,b)=>a.localeCompare(b,"fr",{numeric:true}));
    const classFilter=availableClasses.includes(state.scheduleClassFilter)?state.scheduleClassFilter:"",teacherFilter=state.teachers.some(t=>t.id===state.scheduleTeacherFilter)?state.scheduleTeacherFilter:"";
    const allowedIds=new Set(allowedSectors.map(s=>s.id)),items=(state.schedule||[]).filter(x=>allowedIds.has(x.sectorId)&&(!sectorFilter||x.sectorId===sectorFilter)&&(!classFilter||x.className===classFilter)&&(!teacherFilter||x.teacherId===teacherFilter)).sort((a,b)=>a.day-b.day||slots.indexOf(a.time)-slots.indexOf(b.time)||a.className.localeCompare(b.className,"fr",{numeric:true}));
    return`<div class="page-intro"><div><h2>Emploi du temps</h2><p>${isSupervisor()?`${esc(sector(currentUser().sectorId).name)} · Surveillant général : ${esc(currentUser().name)}`:"Vue générale des cinq secteurs"}</p></div><span class="tag blue">${items.length} cours affichés</span></div>
    <section class="card"><div class="card-head"><h3>Filtres de consultation</h3><span class="tag green">Du lundi au vendredi</span></div><div class="card-body"><div class="filter-row">${isAdmin()?`<label>Secteur<select id="scheduleSector" class="input"><option value="">Tous les secteurs</option>${allowedSectors.map(s=>`<option value="${s.id}" ${s.id===sectorFilter?"selected":""}>${esc(s.name)} — ${esc(s.supervisor)}</option>`).join("")}</select></label>`:""}<label>Classe<select id="scheduleClass" class="input"><option value="">Toutes les classes</option>${availableClasses.map(c=>`<option value="${esc(c)}" ${c===classFilter?"selected":""}>${esc(c)}</option>`).join("")}</select></label><label>Enseignant<select id="scheduleTeacher" class="input"><option value="">Tous les enseignants</option>${state.teachers.filter(t=>t.active).sort((a,b)=>a.name.localeCompare(b.name,"fr")).map(t=>`<option value="${t.id}" ${t.id===teacherFilter?"selected":""}>${esc(t.name)} — ${esc(t.code)}</option>`).join("")}</select></label><label>Recherche<input id="scheduleSearch" class="input" placeholder="Nom, classe, matière…"></label></div></div></section>
    <section class="card" style="margin-top:18px"><div class="card-head"><h3>Cours programmés</h3><small class="muted">L’emploi du temps est automatiquement limité au secteur du surveillant connecté.</small></div><div class="table-wrap"><table id="scheduleTable"><thead><tr><th>N°</th><th>Jour</th><th>Horaire</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Classe</th><th>Matière</th><th>Secteur</th></tr></thead><tbody>${items.length?items.map((x,i)=>{const registered=x.teacherId?teacher(x.teacherId):null,t=registered||{name:x.teacherName||"Non renseigné",code:x.teacherCode||"—"};return`<tr><td>${String(i+1).padStart(3,"0")}</td><td><b>${dayNames[x.day]||x.day}</b></td><td>${esc(x.time)}</td><td>${esc(t.name)}</td><td>${esc(t.code)}</td><td><span class="tag blue">${esc(x.className)}</span></td><td>${esc(x.subject)}</td><td>${esc(sector(x.sectorId).name)}</td></tr>`}).join(""):"<tr><td colspan='8' class='empty'>Aucun cours ne correspond aux filtres sélectionnés.</td></tr>"}</tbody></table></div></section>`
  }

  function renderEvents(){const events=accessibleEvents().slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return`<div class="page-intro"><div><h2>Registre des événements</h2><p>Absences, retards et départs anticipés${isSupervisor()?" · "+esc(sector(currentUser().sectorId).name):""}.</p></div><div class="filter-row"><input id="eventsSearch" class="input" placeholder="Rechercher…">${isAdmin()?'<button class="btn primary" data-action="open-event">+ Ajouter</button>':""}</div></div><section class="card"><div class="card-head"><h3>${events.length} événements actifs</h3><span class="tag green">Mise à jour automatique</span></div><div class="table-wrap"><table id="eventsTable"><thead><tr><th>N°</th><th>Horaire</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Classe</th><th>Matière</th><th>Type</th><th>Statut</th><th>Secteur</th><th></th></tr></thead><tbody>${eventRows(events)}</tbody></table></div></section>`}

  function setReportPeriod(p){state.reportPeriod=p;const now=new Date(),iso=today();if(p==="day"){state.reportStart=iso;state.reportEnd=iso}else if(p==="week"){[state.reportStart,state.reportEnd]=weekRange(now)}else if(p==="month"){state.reportStart=`${iso.slice(0,7)}-01`;state.reportEnd=new Date(now.getFullYear(),now.getMonth()+1,0,12).toISOString().slice(0,10)}else if(p==="term"){const term=state.academicYear.terms.find(([a,b])=>iso>=a&&iso<=b)||state.academicYear.terms[0];[state.reportStart,state.reportEnd]=term}else if(p==="year"){state.reportStart=state.academicYear.start;state.reportEnd=state.academicYear.end}save()}
  function periodEvents(){return accessibleEvents().filter(e=>e.date>=state.reportStart&&e.date<=state.reportEnd)}
  function aggregate(events){const map=new Map();events.filter(e=>e.type==="absence"&&e.status!=="justified").forEach(e=>{const current=map.get(e.teacherId)||{teacher:teacher(e.teacherId),hours:0,classes:new Set(),subjects:new Set()};current.hours+=1;current.classes.add(e.className);(e.jointClasses||[]).forEach(c=>current.classes.add(c));current.subjects.add(e.subject);map.set(e.teacherId,current)});return[...map.values()].sort((a,b)=>b.hours-a.hours||a.teacher.name.localeCompare(b.teacher.name,"fr"))}
  function classRanking(events){const map={};events.filter(e=>e.type==="absence"&&e.status!=="justified").forEach(e=>{[e.className,...(e.jointClasses||[])].forEach(c=>map[c]=(map[c]||0)+1)});return Object.entries(map).sort((a,b)=>b[1]-a[1])}
  function renderReports(){const events=periodEvents(),rows=aggregate(events),classRank=classRanking(events),conf=state.confirmations[state.reportEnd]||{},expected=isSupervisor()?1:5,received=isSupervisor()?(["submitted","approved"].includes(conf[currentUser().sectorId]?.status)?1:0):Object.values(conf).filter(r=>["submitted","approved"].includes(r?.status)).length,complete=received===expected;return`
    <div class="page-intro"><div><h2>Rapports actualisés</h2><p>Consultez, corrigez puis générez la version officielle.</p></div><div class="filter-row"><input id="reportStart" class="input" type="date" value="${state.reportStart}"><input id="reportEnd" class="input" type="date" value="${state.reportEnd}"></div></div>
    <div class="tabs">${[["day","Journalier"],["week","Hebdomadaire"],["month","Mensuel"],["term","Trimestriel"],["year","Annuel"]].map(([v,l])=>`<button class="tab ${state.reportPeriod===v?"active":""}" data-action="period" data-period="${v}">${l}</button>`).join("")}</div>
    <div class="report-banner" style="margin-top:16px"><b>${complete?"✓ RAPPORT COMPLET":"ÉTAT ACTUALISÉ EN TEMPS RÉEL"}</b><span>${fmtDate(state.reportStart)} — ${fmtDate(state.reportEnd)} · ${received}/${expected} secteur${expected>1?"s":""} soumis au dernier jour</span></div>
    <section class="card"><div class="sheet-toolbar"><div class="sheet-title"><span class="excel-mark">X</span><div><b>Synthèse par enseignant</b><small>Seuls les enseignants ayant au moins une heure d’absence comptabilisée</small></div></div><span class="tag green">${rows.length} enseignants</span></div><div class="table-wrap"><table class="editable"><thead><tr><th>N°</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Spécialité</th><th>Heures d’absence</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${String(i+1).padStart(2,"0")}</td><td>${esc(r.teacher.name)}</td><td>${esc(r.teacher.code)}</td><td>${esc(r.teacher.specialty)}</td><td ${isAdmin()?`contenteditable="true" data-teacher="${r.teacher.id}"`:""}><b>${r.hours}</b></td></tr>`).join(""):"<tr><td colspan='5' class='empty'>Aucune absence sur la période.</td></tr>"}</tbody></table></div><div class="report-foot"><small>${events.filter(e=>e.type==="absence"&&e.status!=="justified").length} heures d’absence · Absences justifiées exclues · Données actualisées</small><div class="button-row"><button class="btn ghost" data-action="export" data-format="xlsx">Excel .xlsx</button><button class="btn ghost" data-action="export" data-format="pdf">PDF .pdf</button><button class="btn ghost" data-action="export" data-format="docx">Word .docx</button></div></div></section>
    <div class="grid-3" style="margin-top:18px"><div class="kpi"><div class="kpi-label">ENSEIGNANT LE PLUS ABSENT</div><div class="kpi-value" style="font-size:18px">${rows[0]?esc(rows[0].teacher.name):"—"}</div><div class="kpi-sub">${rows[0]?rows[0].hours+" heures":"Aucune donnée"}</div></div><div class="kpi"><div class="kpi-label">CLASSE LA PLUS TOUCHÉE</div><div class="kpi-value" style="font-size:22px">${classRank[0]?esc(classRank[0][0]):"—"}</div><div class="kpi-sub">${classRank[0]?classRank[0][1]+" heures perdues":"Aucune donnée"}</div></div><div class="kpi"><div class="kpi-label">PÉRIODE</div><div class="kpi-value" style="font-size:18px">${fmtDate(state.reportStart)}</div><div class="kpi-sub">au ${fmtDate(state.reportEnd)}</div></div></div>`}

  function renderUsers(){const roleLabels={principal:"Proviseur",admin:"Administrateur",supervisor:"Surveillant général"},users=Object.entries(state.users).sort(([,a],[,b])=>(a.role==="principal"?-1:b.role==="principal"?1:a.name.localeCompare(b.name,"fr")));return`<div class="page-intro"><div><h2>Utilisateurs et accès</h2><p>Le proviseur enregistre les comptes Gmail autorisés et attribue leurs responsabilités.</p></div><button class="btn primary" data-action="open-user">+ Ajouter un utilisateur</button></div><div class="kpi-grid"><div class="kpi"><div class="kpi-label">COMPTES ACTIFS</div><div class="kpi-value">${users.filter(([,u])=>u.approved).length}</div><div class="kpi-sub">Accès Google autorisés</div></div><div class="kpi"><div class="kpi-label">SURVEILLANTS</div><div class="kpi-value">${users.filter(([,u])=>u.role==="supervisor"&&u.approved).length}</div><div class="kpi-sub">Un responsable par secteur</div></div><div class="kpi"><div class="kpi-label">ADMINISTRATEURS</div><div class="kpi-value">${users.filter(([,u])=>u.role==="admin"&&u.approved).length}</div><div class="kpi-sub">Droits délégués</div></div><div class="kpi"><div class="kpi-label">PROPRIÉTAIRE</div><div class="kpi-value">1</div><div class="kpi-sub">Compte proviseur protégé</div></div></div><section class="card"><div class="card-head"><h3>Comptes enregistrés</h3><input id="userSearch" class="input" placeholder="Rechercher un nom ou une adresse Gmail…"></div><div class="table-wrap"><table id="userTable"><thead><tr><th>N°</th><th>Nom et prénoms</th><th>Gmail</th><th>Téléphone</th><th>Rôle</th><th>Secteur</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${users.map(([key,u],i)=>`<tr><td>${String(i+1).padStart(2,"0")}</td><td><b>${esc(u.name)}</b></td><td>${esc(u.email)}</td><td>${esc(u.phone||"Non renseigné")}</td><td>${esc(roleLabels[u.role]||u.role)}</td><td>${u.sectorId?esc(sector(u.sectorId).name):"—"}</td><td><span class="tag ${u.approved?"green":"gray"}">${u.approved?"Actif":"Désactivé"}</span></td><td>${u.role==="principal"?"<span class='tag blue'>Compte protégé</span>":`<div class="button-row"><button class="btn ghost mini" data-action="open-user" data-id="${esc(key)}">Modifier</button><button class="btn ${u.approved?"danger":"ghost"} mini" data-action="toggle-user" data-id="${esc(key)}">${u.approved?"Désactiver":"Réactiver"}</button></div>`}</td></tr>`).join("")}</tbody></table></div></section>`}

  function renderTeachers(){const activeCount=state.teachers.filter(t=>t.active).length,visible=state.teachers.filter(t=>t.active||state.showInactiveTeachers);return`<div class="page-intro"><div><h2>Répertoire des enseignants</h2><p>Noms, matricules, spécialités et contacts issus du fichier du personnel.</p></div><div class="button-row"><button class="btn ghost" data-action="toggle-inactive-teachers">${state.showInactiveTeachers?"Masquer les retirés":"Afficher les retirés"}</button><button class="btn primary" data-action="open-teacher">+ Ajouter un enseignant</button></div></div><section class="card"><div class="card-head"><h3>${activeCount} enseignants actifs · ${state.teachers.length-activeCount} retirés</h3><input id="teacherSearch" class="input" placeholder="Rechercher un nom, matricule ou téléphone…"></div><div class="table-wrap"><table id="teacherTable"><thead><tr><th>N°</th><th>Nom de l’enseignant</th><th>Matricule</th><th>Spécialité</th><th>Téléphone</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${visible.map((t,i)=>`<tr><td>${String(i+1).padStart(3,"0")}</td><td><b>${esc(t.name)}</b></td><td>${esc(t.code)}</td><td>${esc(t.specialty)}</td><td>${esc(t.phone||"Non renseigné")}</td><td><span class="tag ${t.active?"green":"gray"}">${t.active?"Actif":"Retiré"}</span></td><td><div class="button-row"><button class="btn ghost mini" data-action="open-teacher" data-id="${t.id}">Modifier</button><button class="btn ${t.active?"danger":"ghost"} mini" data-action="toggle-teacher" data-id="${t.id}">${t.active?"Retirer":"Réactiver"}</button></div></td></tr>`).join("")}</tbody></table></div></section>`}

  function allClasses(){return[...new Set(state.sectors.flatMap(s=>s.classes))].sort((a,b)=>a.localeCompare(b,"fr",{numeric:true}))}
  function renderSectors(){const classes=allClasses();return`<div class="page-intro"><div><h2>Organisation des cinq secteurs</h2><p>Chaque classe appartient à un seul secteur. Les changements sont datés et historisés.</p></div><span class="tag green">${classes.length} classes affectées</span></div><div class="grid-3">${state.sectors.map(s=>`<article class="person-card"><div class="person-top"><span class="avatar">${esc(s.supervisor.split(" ").map(x=>x[0]).join("").slice(0,2))}</span><span class="tag green">${s.classes.length} classes</span></div><h4>${esc(s.name)}</h4><small class="eyebrow">SURVEILLANT GÉNÉRAL</small><h3 class="supervisor-name">${esc(s.supervisor)}</h3><p>${esc(s.email)}</p><div class="chips">${s.classes.slice(0,6).map(c=>`<span class="chip">${esc(c)}</span>`).join("")}${s.classes.length>6?`<span class="chip">+${s.classes.length-6}</span>`:""}</div><button class="btn ghost full" data-action="edit-sector" data-id="${s.id}">Modifier le surveillant</button></article>`).join("")}</div><section class="card" style="margin-top:18px"><div class="card-head"><div><h3>Affectation des classes</h3><small class="muted">Sélectionnez le secteur de chaque classe. Les rapports passés restent inchangés.</small></div><input id="classAssignmentSearch" class="input" placeholder="Rechercher une classe…"></div><div class="table-wrap"><table id="classAssignmentTable"><thead><tr><th>N°</th><th>Classe</th><th>Secteur actuel et surveillant</th><th>Nouvelle affectation</th></tr></thead><tbody>${classes.map((className,i)=>{const current=state.sectors.find(s=>s.classes.includes(className));return`<tr><td>${String(i+1).padStart(2,"0")}</td><td><b>${esc(className)}</b></td><td><span class="tag blue">${esc(current?`${current.name} — ${current.supervisor}`:"Non affectée")}</span></td><td><select class="input" data-action="assign-class" data-class="${esc(className)}">${state.sectors.map(s=>`<option value="${s.id}" ${s.id===current?.id?"selected":""}>${esc(`${s.name} — ${s.supervisor}`)}</option>`).join("")}</select></td></tr>`}).join("")}</tbody></table></div></section>`}

  function renderImports(){return`<div class="page-intro"><div><h2>Imports et rapprochement</h2><p>Chargez les fichiers Excel, contrôlez les données puis publiez.</p></div><span class="tag amber">Les imports sont enregistrés dans ce navigateur</span></div><div class="grid-2"><section class="card"><div class="card-head"><h3>Fichier du personnel</h3><span class="tag blue">Excel / CSV</span></div><div class="card-body"><div class="dropzone"><div class="drop-icon">⇧</div><b>Importer le fichier du personnel</b><p>Nom, matricule, fonction, discipline et statut.</p><button class="btn primary" data-action="pick-file" data-type="staff">Choisir un fichier</button></div></div></section><section class="card"><div class="card-head"><h3>Emploi du temps</h3><span class="tag blue">Excel / CSV</span></div><div class="card-body"><div class="dropzone"><div class="drop-icon">⇧</div><b>Importer l’emploi du temps</b><p>Horaire, classe, jour, matière et enseignant.</p><button class="btn primary" data-action="pick-file" data-type="schedule">Choisir un fichier</button></div></div></section></div><section class="card" style="margin-top:18px"><div class="card-head"><h3>Historique des imports</h3></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Fichier</th><th>Type</th><th>Lignes reconnues</th><th>Statut</th></tr></thead><tbody>${state.imports.length?state.imports.map(x=>`<tr><td>${new Date(x.at).toLocaleString("fr-FR")}</td><td><b>${esc(x.name)}</b></td><td>${x.type==="staff"?"Personnel":"Emploi du temps"}</td><td>${x.rows}</td><td><span class="tag green">Publié</span></td></tr>`).join(""):"<tr><td colspan='5' class='empty'>Aucun import effectué dans cette démonstration.</td></tr>"}</tbody></table></div></section>`}

  function renderAudit(){return`<div class="page-intro"><div><h2>Journal d’audit</h2><p>Historique non modifiable des actions importantes.</p></div><button class="btn ghost" data-action="reset-demo">Réinitialiser la démonstration</button></div><section class="card">${state.audit.map(a=>`<div class="audit-item"><time>${new Date(a.at).toLocaleString("fr-FR")}</time><div><b>${esc(a.action)}</b><small>${esc(a.detail)}</small></div><span class="tag blue">${esc(a.actor)}</span></div>`).join("")}</section>`}

  function bindPageActions(){
    $$('[data-page]').forEach(el=>el.onclick=()=>{state.currentPage=el.dataset.page;save();render();$(".sidebar").classList.remove("open")});
    $$('[data-action="open-event"]').forEach(el=>el.onclick=()=>openEvent());
    $$('[data-action="edit-event"]').forEach(el=>el.onclick=()=>{const event=state.events.find(e=>e.id===el.dataset.id);if(event?.submissionId&&!isPrincipal())return toast("Seul le proviseur peut modifier un événement déjà soumis",true);openEvent(el.dataset.id)});
    $$('[data-action="remove-event"]').forEach(el=>el.onclick=()=>removeEvent(el.dataset.id));
    $$('[data-action="confirm-sector"]').forEach(el=>el.onclick=()=>confirmSector(el.dataset.id));
    $$('[data-action="submit-daily"]').forEach(el=>el.onclick=()=>submitDaily());
    $$('[data-action="logout"]').forEach(el=>el.onclick=()=>logout());
    $$('[data-action="period"]').forEach(el=>el.onclick=()=>{setReportPeriod(el.dataset.period);render()});
    $$('[data-action="export"]').forEach(el=>el.onclick=()=>exportReport(el.dataset.format));
    $$('[data-action="open-teacher"]').forEach(el=>el.onclick=()=>openTeacher(el.dataset.id));
    $$('[data-action="toggle-teacher"]').forEach(el=>el.onclick=()=>toggleTeacher(el.dataset.id));
    $$('[data-action="open-user"]').forEach(el=>el.onclick=()=>openUser(el.dataset.id));
    $$('[data-action="toggle-user"]').forEach(el=>el.onclick=()=>toggleUser(el.dataset.id));
    $$('[data-action="toggle-inactive-teachers"]').forEach(el=>el.onclick=()=>{state.showInactiveTeachers=!state.showInactiveTeachers;save();render()});
    $$('[data-action="edit-sector"]').forEach(el=>el.onclick=()=>editSector(el.dataset.id));
    $$('[data-action="assign-class"]').forEach(el=>el.onchange=()=>assignClass(el.dataset.class,el.value));
    $$('[data-action="pick-file"]').forEach(el=>el.onclick=()=>{$("#filePicker").dataset.type=el.dataset.type;$("#filePicker").click()});
    const es=$("#eventsSearch");if(es)es.oninput=()=>filterTable("#eventsTable",es.value);
    const scheduleSearch=$("#scheduleSearch");if(scheduleSearch)scheduleSearch.oninput=()=>filterTable("#scheduleTable",scheduleSearch.value);
    const scheduleSector=$("#scheduleSector");if(scheduleSector)scheduleSector.onchange=()=>{state.scheduleSectorFilter=scheduleSector.value;state.scheduleClassFilter="";save();render()};
    const scheduleClass=$("#scheduleClass");if(scheduleClass)scheduleClass.onchange=()=>{state.scheduleClassFilter=scheduleClass.value;save();render()};
    const scheduleTeacher=$("#scheduleTeacher");if(scheduleTeacher)scheduleTeacher.onchange=()=>{state.scheduleTeacherFilter=scheduleTeacher.value;save();render()};
    const ts=$("#teacherSearch");if(ts)ts.oninput=()=>filterTable("#teacherTable",ts.value);
    const us=$("#userSearch");if(us)us.oninput=()=>filterTable("#userTable",us.value);
    const cs=$("#classAssignmentSearch");if(cs)cs.oninput=()=>filterTable("#classAssignmentTable",cs.value);
    const rs=$("#reportStart"),re=$("#reportEnd");if(rs)rs.onchange=()=>{state.reportStart=rs.value;state.reportPeriod="custom";save();render()};if(re)re.onchange=()=>{state.reportEnd=re.value;state.reportPeriod="custom";save();render()};
    $$('[contenteditable][data-teacher]').forEach(td=>td.onblur=()=>{const value=Math.max(0,parseInt(td.textContent)||0);td.textContent=value;audit("Correction du rapport",`${teacher(td.dataset.teacher).name} : total affiché ajusté à ${value} h`);toast("Modification enregistrée dans le journal d’audit")});
    const reset=$('[data-action="reset-demo"]');if(reset)reset.onclick=()=>{if(confirm("Réinitialiser toutes les données de démonstration ?")){state=seed();state.loggedIn=true;state.currentUser="principal";save();showApp();toast("Démonstration réinitialisée")}}
  }
  function filterTable(selector,q){q=normalize(q);$$(selector+" tbody tr").forEach(tr=>tr.hidden=!normalize(tr.textContent).includes(q))}

  function openEvent(id){const e=id?state.events.find(x=>x.id===id):null,sectorId=isSupervisor()?currentUser().sectorId:e?.sectorId||state.sectors[0].id;if(isSupervisor()&&reportLocked(e?.date||today(),sectorId))return toast("Le rapport journalier est verrouillé",true);$("#eventDialogTitle").textContent=e?"Modifier l’événement":"Nouvel événement";$("#eventId").value=e?.id||"";$("#eventDate").value=e?.date||today();$("#eventDate").disabled=isSupervisor();$("#eventTime").innerHTML=slots.map(s=>`<option ${e?.time===s?"selected":""}>${s}</option>`).join("");$("#teacherSuggestions").innerHTML=state.teachers.filter(t=>t.active).map(t=>`<option value="${esc(teacherLabel(t))}"></option>`).join("");setTeacherInput(e?.teacherId||"");const classes=sector(sectorId).classes||[];$("#eventClass").innerHTML=classes.map(c=>`<option ${e?.className===c?"selected":""}>${esc(c)}</option>`).join("");$("#eventSubject").value=e?.subject||"";$("#eventType").value=e?.type||"absence";$("#eventBand").value=e?.band||"";$("#eventStatus").value=e?.status||"pending";$("#eventStatus").disabled=isSupervisor();$("#eventSector").innerHTML=(isSupervisor()?[sector(sectorId)]:state.sectors).map(s=>`<option value="${s.id}" ${s.id===sectorId?"selected":""}>${esc(s.name)}</option>`).join("");$("#eventSector").disabled=isSupervisor();$("#eventJointClasses").value=(e?.jointClasses||[]).join(", ");$("#eventNote").value=e?.note||"";$("#eventScheduleHint").textContent=e?"Événement existant · modification manuelle autorisée.":"Sélectionnez d’abord l’horaire et la classe.";if(!e)autoFillFromSchedule();$("#eventDialog").showModal()}
  function reopenDailyReport(date,sectorId){return}
  function saveEvent(){const id=$("#eventId").value,selectedTeacher=syncTeacherInput();if(!selectedTeacher)return toast("Sélectionnez un enseignant dans la liste proposée",true);const data={date:$("#eventDate").value,time:$("#eventTime").value,teacherId:selectedTeacher.id,className:$("#eventClass").value,subject:$("#eventSubject").value.trim(),type:$("#eventType").value,band:$("#eventType").value==="absence"?"":$("#eventBand").value,status:isSupervisor()?"pending":$("#eventStatus").value,sectorId:isSupervisor()?currentUser().sectorId:$("#eventSector").value,jointClasses:$("#eventJointClasses").value.split(",").map(x=>x.trim()).filter(Boolean),note:$("#eventNote").value.trim()};if(!data.date||!data.teacherId||!data.subject||!data.className)return toast("Champs obligatoires manquants",true);if(isSupervisor()&&(data.date!==today()||reportLocked(data.date,data.sectorId)))return toast("Vous ne pouvez modifier que le rapport ouvert du jour",true);const t=teacher(data.teacherId),summary=`${typeLabel(data)}\n${data.time} · ${t.name} (${t.code})\n${data.className} · ${data.subject}\n\nConfirmer l’enregistrement ?`;if(!confirm(summary))return;if(id){Object.assign(state.events.find(e=>e.id===id),data,{updatedAt:new Date().toISOString()});audit("Événement modifié",`${t.name} · ${data.date} · ${data.time}`)}else{state.events.push({id:uid("e"),...data,cancelled:false,createdAt:new Date().toISOString()});audit("Événement créé",`${t.name} · ${data.date} · ${data.time}`)}if(isSupervisor())reopenDailyReport(data.date,data.sectorId);save();$("#eventDialog").close();render();toast("Événement enregistré")}
  function removeEvent(id){const event=state.events.find(e=>e.id===id&&!e.cancelled);if(!event)return;const allowed=event.submissionId?isPrincipal():(isAdmin()||(isSupervisor()&&event.sectorId===currentUser().sectorId&&event.date===today()&&!reportLocked(event.date,event.sectorId)));if(!allowed)return toast(event.submissionId?"Seul le proviseur peut retirer un événement déjà soumis":"Cet événement est verrouillé",true);const t=teacher(event.teacherId);if(!confirm(`Retirer cet événement actif ?\n\n${event.time} · ${t.name}\n${event.className} · ${event.subject}\n\nIl restera conservé dans le journal d’audit.`))return;event.cancelled=true;event.cancelledAt=new Date().toISOString();event.cancelledBy=currentUser().email;audit("Événement retiré",`${t.name} · ${event.date} · ${event.time} · ${event.className}${event.submissionId?" · rapport déjà soumis":""}`);save();render();toast("Événement retiré")}
  function submitDaily(){if(!isSupervisor())return;const checkbox=$("#reportAttestation");if(!checkbox?.checked)return toast("Veuillez cocher l’attestation avant la soumission",true);const d=today(),sid=currentUser().sectorId,pendingEvents=activeEvents().filter(e=>e.date===d&&e.sectorId===sid&&!e.submissionId),count=pendingEvents.length,submissionNumber=(state.submissions||[]).filter(s=>s.date===d&&s.sectorId===sid).length+1;if(!confirm(`Soumettre le rapport n° ${submissionNumber} du ${d} pour ${sector(sid).name} ?\n${count?count+" nouvel(aux) événement(s)":"Rapport Néant"}\n\nLes événements de ce rapport seront ensuite verrouillés.`))return;const submissionId=uid("submission"),at=new Date().toISOString(),eventIds=pendingEvents.map(e=>e.id);pendingEvents.forEach(e=>{e.submissionId=submissionId;e.submittedAt=at;e.submittedBy=currentUser().email});state.submissions??=[];state.submissions.push({id:submissionId,date:d,sectorId:sid,number:submissionNumber,eventIds,status:"submitted",at,by:currentUser().email,attested:true});state.confirmations[d]??={};state.confirmations[d][sid]={status:"submitted",submissionId,submissionCount:submissionNumber,at,by:currentUser().email,attested:true,eventCount:count};audit("Rapport journalier soumis",`${sector(sid).name} · rapport n° ${submissionNumber} · ${count?count+" événement(s) verrouillé(s)":"Néant"} · notification au proviseur`);save();render();toast(`Rapport n° ${submissionNumber} soumis au proviseur`)}
  function confirmSector(id){if(!isAdmin())return;const d=today(),r=dayReport(d,id);if(!r||r.status!=="submitted")return toast("Ce rapport n’est pas prêt à être approuvé",true);r.status="approved";r.approvedAt=new Date().toISOString();r.approvedBy=currentUser().email;const submission=(state.submissions||[]).find(s=>s.id===r.submissionId);if(submission){submission.status="approved";submission.approvedAt=r.approvedAt;submission.approvedBy=r.approvedBy}audit("Rapport journalier approuvé",`${sector(id).name} · rapport n° ${r.submissionCount||1} · ${d}`);save();render();toast("Rapport approuvé")}
  function editSector(id){if(!isAdmin())return;const s=state.sectors.find(x=>x.id===id);if(!s)return;$("#sectorDialogTitle").textContent=`Modifier le surveillant · ${s.name}`;$("#sectorIdInput").value=s.id;$("#sectorSupervisorInput").value=s.supervisor||"";$("#sectorEmailInput").value=s.email||"";$("#sectorDialog").showModal()}
  function saveSector(){const id=$("#sectorIdInput").value,name=$("#sectorSupervisorInput").value.trim(),email=$("#sectorEmailInput").value.trim(),s=state.sectors.find(x=>x.id===id);if(!s||!name||!email)return toast("Le nom et l’adresse Gmail sont requis",true);const previousSupervisor=s.supervisor,previousEmail=s.email;s.history??=[];s.history.push({from:new Date().toISOString(),previousSupervisor,previousEmail,newSupervisor:name,newEmail:email,changedBy:currentUser().email});s.supervisor=name;s.email=email;const userKey=Object.keys(state.users).find(key=>state.users[key].role==="supervisor"&&state.users[key].sectorId===id);if(userKey){state.users[userKey].name=name;state.users[userKey].email=email}audit("Surveillant modifié",`${s.name} · ${previousSupervisor} (${previousEmail}) → ${name} (${email})`);save();$("#sectorDialog").close();$("#sectorForm").reset();render();toast("Surveillant mis à jour")}
  function assignClass(className,newSectorId){if(!isAdmin())return;const previous=state.sectors.find(s=>s.classes.includes(className)),next=state.sectors.find(s=>s.id===newSectorId);if(!next||previous?.id===next.id)return;state.sectors.forEach(s=>s.classes=s.classes.filter(c=>c!==className));next.classes.push(className);next.classes.sort((a,b)=>a.localeCompare(b,"fr",{numeric:true}));state.classAssignmentHistory??=[];state.classAssignmentHistory.unshift({className,fromSectorId:previous?.id||null,toSectorId:next.id,effectiveDate:today(),at:new Date().toISOString(),by:currentUser().email});(state.schedule||[]).filter(item=>item.className===className).forEach(item=>item.sectorId=next.id);audit("Classe réaffectée",`${className} · ${previous?.name||"Non affectée"} → ${next.name} · effet à compter du ${today()}`);save();render();toast(`${className} affectée à ${next.name}`)}
  function logout(){audit("Déconnexion",currentUser()?.email||"");state.loggedIn=false;state.currentUser=null;save();showApp()}
  function updateUserSectorVisibility(){const supervisor=$("#userRoleInput").value==="supervisor";$("#userSectorLabel").classList.toggle("hidden",!supervisor);$("#userSectorInput").required=supervisor}
  function openUser(key){if(!isPrincipal())return;const user=key?state.users[key]:null;if(user?.role==="principal")return toast("Le compte du proviseur est protégé",true);$("#userDialogTitle").textContent=user?"Modifier un utilisateur":"Ajouter un utilisateur";$("#userKeyInput").value=key||"";$("#userNameInput").value=user?.name||"";$("#userEmailInput").value=user?.email||"";$("#userPhoneInput").value=user?.phone==="Non renseigné"?"":user?.phone||"";$("#userRoleInput").value=user?.role||"supervisor";$("#userSectorInput").innerHTML=state.sectors.map(s=>`<option value="${s.id}" ${s.id===user?.sectorId?"selected":""}>${esc(s.name)} — ${esc(s.supervisor)}</option>`).join("");updateUserSectorVisibility();$("#userDialog").showModal()}
  function saveUser(){if(!isPrincipal())return;const existingKey=$("#userKeyInput").value,name=$("#userNameInput").value.trim(),email=$("#userEmailInput").value.trim().toLowerCase(),phone=$("#userPhoneInput").value.trim()||"Non renseigné",role=$("#userRoleInput").value,sectorId=role==="supervisor"?$("#userSectorInput").value:null;if(!name||!email||!role||role==="supervisor"&&!sectorId)return toast("Complétez les informations obligatoires",true);const duplicate=Object.entries(state.users).find(([key,user])=>key!==existingKey&&normalize(user.email)===normalize(email));if(duplicate)return toast("Cette adresse Gmail est déjà enregistrée",true);const key=existingKey||uid("user"),previous=state.users[key];if(role==="supervisor"){Object.entries(state.users).forEach(([otherKey,user])=>{if(otherKey!==key&&user.role==="supervisor"&&user.sectorId===sectorId)user.approved=false});const assignedSector=sector(sectorId);assignedSector.supervisor=name;assignedSector.email=email}state.users[key]={...(previous||{}),name,email,phone,role,sectorId,approved:previous?.approved!==false};audit(previous?"Utilisateur modifié":"Utilisateur ajouté",`${name} · ${email} · ${role==="supervisor"?sector(sectorId).name:"Administrateur"}`);save();refreshLoginAccounts();$("#userDialog").close();$("#userForm").reset();render();toast(previous?"Utilisateur mis à jour":"Utilisateur ajouté")}
  function toggleUser(key){if(!isPrincipal())return;const user=state.users[key];if(!user||user.role==="principal")return toast("Le compte du proviseur est protégé",true);const action=user.approved?"désactiver":"réactiver";if(!confirm(`${action[0].toUpperCase()+action.slice(1)} l’accès de ${user.name} ?`))return;user.approved=!user.approved;audit(user.approved?"Utilisateur réactivé":"Utilisateur désactivé",`${user.name} · ${user.email}`);save();refreshLoginAccounts();render();toast(`Accès ${user.approved?"réactivé":"désactivé"}`)}
  function openTeacher(id){const t=id?state.teachers.find(x=>x.id===id):null;$("#teacherIdInput").value=t?.id||"";$("#teacherDialogTitle").textContent=t?"Modifier un enseignant":"Ajouter un enseignant";$("#saveTeacher").textContent=t?"Enregistrer les modifications":"Ajouter";$("#teacherNameInput").value=t?.name||"";$("#teacherCodeInput").value=t?.code||"";$("#teacherSpecialtyInput").value=t?.specialty||"";$("#teacherPhoneInput").value=t?.phone==="Non renseigné"?"":t?.phone||"";$("#teacherDialog").showModal()}
  function saveTeacher(){const id=$("#teacherIdInput").value,name=$("#teacherNameInput").value.trim(),rawCode=$("#teacherCodeInput").value.trim(),code=normalize(rawCode)==="VACATAIRE"?"VACATAIRE":rawCode,specialty=$("#teacherSpecialtyInput").value.trim(),phone=$("#teacherPhoneInput").value.trim()||"Non renseigné";if(!name||!code||!specialty)return toast("Le nom, le matricule et la spécialité sont requis",true);if(id){const t=state.teachers.find(x=>x.id===id);if(!t)return;const previous={name:t.name,code:t.code,specialty:t.specialty,phone:t.phone||"Non renseigné"};Object.assign(t,{name,code,specialty,phone});audit("Fiche enseignant modifiée",`${previous.name} · téléphone ${previous.phone} → ${phone} · matricule ${previous.code} → ${code}`);toast("Fiche enseignant mise à jour")}else{state.teachers.push({id:uid("t"),name,code,specialty,phone,active:true});audit("Enseignant ajouté",`${name} · ${code} · ${phone}`);toast("Enseignant ajouté")}save();$("#teacherDialog").close();$("#teacherForm").reset();render()}
  function toggleTeacher(id){if(!isAdmin())return;const t=state.teachers.find(x=>x.id===id);if(!t)return;if(t.active){const scheduled=(state.schedule||[]).filter(x=>x.teacherId===id).length;if(!confirm(`Retirer ${t.name} de la liste active ?${scheduled?`\n\n${scheduled} cours de l’emploi du temps lui sont encore associés et devront être réaffectés.`:""}\n\nSes anciennes données seront conservées.`))return;t.active=false;audit("Enseignant retiré",`${t.name} · ${t.code} · historique conservé`);toast("Enseignant retiré de la liste active")}else{t.active=true;audit("Enseignant réactivé",`${t.name} · ${t.code}`);toast("Enseignant réactivé")}save();render()}

  function reportMatrix(){const rows=aggregate(periodEvents());return[["N°","Nom de l’enseignant","Matricule","Spécialité","Heures d’absence"],...rows.map((r,i)=>[i+1,r.teacher.name,r.teacher.code,r.teacher.specialty,r.hours])]}
  function exportReport(format){const matrix=reportMatrix();if(matrix.length===1)return toast("Aucune donnée à exporter",true);const title=`Rapport TeacherWatch ${state.reportStart} au ${state.reportEnd}`;if(format==="xlsx")downloadBytes(buildXlsx(matrix,title),fileName("xlsx"),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");else if(format==="docx")downloadBytes(buildDocx(matrix,title),fileName("docx"),"application/vnd.openxmlformats-officedocument.wordprocessingml.document");else downloadBytes(buildPdf(matrix,title),fileName("pdf"),"application/pdf");audit("Rapport généré",`${format.toUpperCase()} · ${state.reportStart} au ${state.reportEnd}`);toast(`Rapport ${format.toUpperCase()} généré`)}
  function fileName(ext){return`TeacherWatch_${state.reportStart}_${state.reportEnd}.${ext}`}
  function downloadBytes(bytes,name,type){const blob=new Blob([bytes],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  const xml=v=>esc(v).replace(/&#39;/g,"&apos;");
  function crcTable(){const t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t}const CRC=crcTable();
  function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=CRC[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
  function u16(v){return new Uint8Array([v&255,(v>>>8)&255])}function u32(v){return new Uint8Array([v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255])}
