  async function readImport(file,type){try{let matrix;if(file.name.toLowerCase().endsWith(".csv"))matrix=parseCsv(await file.text());else matrix=await parseXlsx(await file.arrayBuffer());const result=applyImport(matrix,type);state.imports.unshift({id:uid("i"),at:new Date().toISOString(),name:file.name,type,rows:result});audit("Fichier importé",`${file.name} · ${result} lignes reconnues`);save();render();toast(`${result} lignes importées`)}catch(err){console.error(err);toast("Import impossible : fichier non reconnu",true)}}
  function parseCsv(text){return text.split(/\r?\n/).filter(Boolean).map(line=>{const sep=line.includes(";")?";":",";return line.split(sep).map(v=>v.replace(/^"|"$/g,"").trim())})}
  function applyImport(matrix,type){const headerIndex=matrix.findIndex(r=>r.some(c=>normalize(c).includes(type==="staff"?"MATRICULE":"HEURE")));if(headerIndex<0)throw new Error("Header not found");const headers=matrix[headerIndex].map(normalize),rows=matrix.slice(headerIndex+1).filter(r=>r.some(Boolean));if(type==="staff"){const ni=headers.findIndex(x=>x.includes("NOMS ET PRENOMS")),mi=headers.findIndex(x=>x.includes("MATRICULE")),si=headers.findIndex(x=>x.includes("DISCIPLINE")),pi=headers.findIndex(x=>x.includes("CONTACT")||x.includes("TELEPHONE")),fi=headers.findIndex(x=>x.includes("FONCTION OCCUPEE")||x==="FONCTION");let count=0;rows.forEach(r=>{const name=String(r[ni]||"").trim(),rawCode=String(r[mi]||"").trim(),code=normalize(rawCode)==="VACATAIRE"?"VACATAIRE":rawCode,specialty=String(r[si]||"Non renseignée").trim(),phone=pi>=0&&r[pi]?`+237 ${String(r[pi]).replace(/\D/g,"").replace(/^237/,"")}`:"Non renseigné",role=fi>=0?normalize(r[fi]):"ENSEIGNANT";if(!name||!code||!role.includes("ENSEIGNANT"))return;const existing=state.teachers.find(t=>normalize(t.name)===normalize(name)||(normalize(code)!=="VACATAIRE"&&normalize(t.code)===normalize(code)));if(existing)Object.assign(existing,{name,code,specialty:specialty||existing.specialty,phone:phone!=="Non renseigné"?phone:existing.phone});else state.teachers.push({id:uid("t"),name,code,specialty:specialty||"Non renseignée",phone,active:true});count++});return count}else{const ci=headers.findIndex(x=>x.includes("CLASSE")),ei=headers.findIndex(x=>x.includes("ENSEIGNANT"));let count=0;rows.forEach(r=>{const c=String(r[ci]||"").trim(),n=String(r[ei]||"").trim();if(c&&!state.sectors.some(s=>s.classes.includes(c)))state.sectors[count%5].classes.push(c);if(n&&!/^\d+$/.test(n)&&!state.teachers.some(t=>normalize(t.name).startsWith(normalize(n))||normalize(n).startsWith(normalize(t.name))))state.teachers.push({id:uid("t"),name:n,code:"À RAPPROCHER",specialty:"À RAPPROCHER",phone:"Non renseigné",active:true});count++});return count}}
  async function parseXlsx(buffer){const files=await unzip(buffer),decoder=new TextDecoder(),strings=[];if(files["xl/sharedStrings.xml"]){const doc=new DOMParser().parseFromString(decoder.decode(files["xl/sharedStrings.xml"]),"application/xml");doc.querySelectorAll("si").forEach(si=>strings.push([...si.querySelectorAll("t")].map(t=>t.textContent).join("")))}const path=Object.keys(files).find(k=>/^xl\/worksheets\/sheet\d+\.xml$/.test(k));if(!path)throw new Error("Worksheet missing");const doc=new DOMParser().parseFromString(decoder.decode(files[path]),"application/xml"),matrix=[];doc.querySelectorAll("row").forEach(row=>{const out=[];row.querySelectorAll("c").forEach(c=>{const ref=c.getAttribute("r")||"A1",col=ref.match(/[A-Z]+/)[0].split("").reduce((n,x)=>n*26+x.charCodeAt(0)-64,0)-1,type=c.getAttribute("t"),v=c.querySelector("v")?.textContent??c.querySelector("t")?.textContent??"";out[col]=type==="s"?strings[Number(v)]??v:v});matrix.push(out)});return matrix}
