  $("#mainNav").addEventListener("click",e=>{const b=e.target.closest("[data-page]");if(b){state.currentPage=b.dataset.page;save();render()}});$("#menuToggle").onclick=()=>$(".sidebar").classList.toggle("open");$$('[data-action="toggle-lang"]').forEach(b=>b.onclick=()=>{state.lang=state.lang==="fr"?"en":"fr";save();applyI18n();if(state.loggedIn)render()});$$('[data-action="close-event"]').forEach(b=>b.onclick=()=>{$("#eventDialog").close();$("#eventForm").reset();$("#eventTeacherId").value="";$("#eventTeacherCode").value=""});$("#saveEvent").onclick=e=>{e.preventDefault();saveEvent()};$("#saveTeacher").onclick=e=>{e.preventDefault();saveTeacher()};$("#saveSector").onclick=e=>{e.preventDefault();saveSector()};$("#eventTeacher").oninput=()=>syncTeacherInput(false);$("#eventTeacher").onchange=()=>syncTeacherInput(true);$("#eventDate").onchange=autoFillFromSchedule;$("#eventTime").onchange=autoFillFromSchedule;$("#eventClass").onchange=autoFillFromSchedule;$("#eventSector").onchange=()=>{const classes=sector($("#eventSector").value).classes||[];$("#eventClass").innerHTML=classes.map(c=>`<option>${esc(c)}</option>`).join("");autoFillFromSchedule()};$("#filePicker").onchange=e=>{const file=e.target.files[0];if(file)readImport(file,e.target.dataset.type);e.target.value=""};loginInit();showApp();
